import math
def control(obs):
    cam=obs.get('views',{}).get('camera')
    h=obs['hitch_deg']
    if not cam: return (0,0,-23)
    a=math.radians(obs['rig']['trailer_heading_deg'])
    rear=obs['rig']['trailer_rear']; origin=cam['origin']
    sides=[[],[]]
    for b,d in cam.get('walls',[]):
        b=math.radians(b)
        dx=origin[0]+d*math.cos(b)-rear[0]; dy=origin[1]+d*math.sin(b)-rear[1]
        s=-dx*math.cos(a)-dy*math.sin(a)
        n=-dx*math.sin(a)+dy*math.cos(a)
        if s>0.4: sides[0 if n<0 else 1].append((s,n))
    def at(points,L):
        points=sorted(points)
        for p,q in zip(points,points[1:]):
            if p[0]<=L<=q[0] and q[0]>p[0]: return p[1]+(q[1]-p[1])*(L-p[0])/(q[0]-p[0])
        return min(points,key=lambda p:abs(p[0]-L))[1]
    if not all(sides): return (max(-34,min(34,2*h)),-0.35,-23)
    L=3.5
    n=(at(sides[0],L)+at(sides[1],L))/2
    desired=math.degrees(math.atan2(2*3.5*n,L*L))
    desired=max(-30,min(30,desired))
    steer=max(-34,min(34,2.4*h-1.7*desired))
    return (steer,-0.65,-23)

