start=None
phase=0
seen=set()
def control(obs):
 global start,phase
 if start is None: start=obs['progress']['covered']
 h=obs['hitch_deg']
 steer=max(-35,min(35,3*(h+20)-23))
 if obs['progress']['covered']-start<0.55:
  return (steer,-0.18,60)
 gazes=[60,140,-140]
 gaze=gazes[phase]
 if obs['head']['settled'] and abs(obs['head']['gaze_deg']-gaze)<3 and phase not in seen:
  seen.add(phase)
  v=obs['views'].get('direct',{})
  print('CLEARANCE',gaze,'rails',v.get('walls',[]),'bay',v.get('target_corners',[]))
  if phase<2: phase+=1
  else: wake('Bend and front clearance checked')
 return (steer,0,gazes[phase])

