import math
distance=0.0
phase=0
seen=set()
def control(obs):
 global distance,phase
 distance+=max(0,obs['motion']['v_mps'])*obs['dt']
 if distance<1.3:
  return (-25,0.22,60)
 if distance<1.9:
  return (0,0.18,60)
 gazes=[60,140,-140]
 gaze=gazes[phase]
 if abs(obs['motion']['v_mps'])<0.02 and obs['head']['settled'] and abs(obs['head']['gaze_deg']-gaze)<3 and phase not in seen:
  seen.add(phase)
  v=obs['views'].get('direct',{})
  points=[]
  for b,d in v.get('walls',[]):
   r=math.radians(b)
   points.append([round(0.1+d*math.cos(r),2),round(d*math.sin(r),2)])
  print('RESET',gaze,'RAILS',points,'BAY',v.get('target_corners',[]),'HITCH',obs['hitch_deg'],'TARGET',obs['target'])
  if phase<2: phase+=1
  else: wake('Longer reset surveyed')
 return (0,0,gazes[phase])

