import math
def control(o):
    h=o['hitch_deg']; cam=o['views'].get('camera'); desired=0.0
    if cam:
        sides=[[],[]]
        for b,d in cam.get('walls',[]):
            a=math.radians(b+h); s=-d*math.cos(a); y=d*math.sin(a)
            if 2<s<13:
                sides[0 if y>0 else 1].append((s,y))
        if all(sides):
            vals=[]
            for pts in sides:
                pts.sort(key=lambda p:abs(p[0]-7))
                pts=pts[:3]
                vals.append(sum(p[1] for p in pts)/len(pts))
            e=(vals[0]+vals[1])/2
            desired=max(-35,min(35,math.degrees(math.atan(20.4*e/49))))
    steer=math.degrees(math.atan(3.9/10.2*math.sin(math.radians(h))))+1.5*(h-desired)
    return (max(-42,min(42,steer)), -0.9, -41)

